<?php
namespace App\Models;
use App\Casts\DateOnly;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
/** Provides performance goal behavior within the WorkIntel application. */ class PerformanceGoal extends Model{protected $fillable=['uuid','workspace_id','member_id','parent_goal_id','title','description','category','status','progress_percent','weight','target_value','current_value','unit','start_date','due_date','completed_at','created_by'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['start_date'=>DateOnly::class,'due_date'=>DateOnly::class,'completed_at'=>'datetime','target_value'=>'decimal:2','current_value'=>'decimal:2'];}/** Handles the member operation for the current WorkIntel workflow. */ public function member():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'member_id');}/** Updates updates data for the requested resource. */ public function updates():HasMany{return $this->hasMany(PerformanceGoalUpdate::class);}}
